package com.bank.depreward.service;

import java.util.logging.Logger;

// Maximum sum of a strictly increasing subsequence of deposit amounts.
public class DepositRewardService {
    private static final Logger log = Logger.getLogger(DepositRewardService.class.getName());

    public int maxRisingDepositSum(int[] deposits) {
        int n = deposits.length;
        if (n == 0) return 0;
        int[] sum = deposits.clone();               // sum[i] seeded with element value
        int best = deposits[0];
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (deposits[j] < deposits[i])        // strictly rising
                    sum[i] = Math.max(sum[i], sum[j] + deposits[i]);
            }
            best = Math.max(best, sum[i]);
        }
        final int r = best;
        log.info(() -> "Max rising deposit sum = " + r);
        return best;
    }
}
