package com.bank.depreward;

import com.bank.depreward.service.DepositRewardService;
import java.util.logging.Logger;

public class DepositRewardApplication {
    private static final Logger log = Logger.getLogger(DepositRewardApplication.class.getName());

    public static void main(String[] args) {
        DepositRewardService service = new DepositRewardService();
        int[] deposits = {4, 1, 3, 7};
        int total = service.maxRisingDepositSum(deposits);
        log.info("Maximum rising deposit sum is " + total);
    }
}
